import { dirname, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { arch, release, loadavg } from 'node:os';
import { PUBLIC_SECURITY_HEADERS } from './game-cli.mjs';
import {
  installAudioProof,
  evaluateAudioProof,
  audioProofOptions,
  readAudioFailureContext,
