  for (const row of plan.rows) {
    assert.equal(row.id, `${plan.phase}-${plan.engine}-r${plan.repetition}-${row.source}`);
    assert.equal(row.kind, plan.phase === 'diagnostics' ? 'diagnostics' : 'lifecycle');
    assert.equal(row.engine, plan.engine);
