    assert(Number.isSafeInteger(ref.bytes) && ref.bytes > 0 && ref.bytes <= 16384);
    assert.match(ref.sha256, /^[a-f0-9]{64}$/);
  }
  assert.equal(
    plan.recipes.opening.sha256,
